import type { ReactNode } from 'react';
import { Label } from '@gravity-ui/uikit';
import type { LayoutItem, Rect } from './layout';
import { BarChart, DataTable, LineChart, SegmentedBar, Sparkline, fmt, type Column } from './charts';
import {
  avgCheckTrend,
  change,
  channelShares,
  conversionTrend,
  dayLabels,
  ordersCurrent,
  ordersPrevious,
  ordersTrend,
  recentOrders,
  revenueCurrent,
  revenuePrevious,
  revenueTrend,
  segmentShares,
  totalsCurrent,
  totalsPrevious,
  type OrderStatus,
} from './data';
import { viz } from './theme';

export interface WidgetDef {
  id: string;
  title: string;
  subtitle?: string;
  /** Smallest size the user can resize to, in grid units. */
  minW: number;
  minH: number;
  /** Position and size on first load. */
  layout: Rect;
  body: ReactNode;
  /** Table-view twin. Present on every chart; toggled from the widget header. */
  table?: ReactNode;
}

// ---------- stat tile ----------

