/* Dashboard chrome and chart styles. Colors come from the validated palette in theme.ts. */

.dash-root {
  box-sizing: border-box;
  min-height: 100vh;
  padding: 24px;
  background: #f9f9f7;
  color: #0b0b0b;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

.dash-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.dash-header h1 {
  margin: 0 0 4px;
}

.dash-hint {
  max-width: 720px;
  margin: 0;
}

/* ---------- grid ---------- */

.dash-grid {
  position: relative;
  width: 100%;
}

.dash-placeholder {
  position: absolute;
  box-sizing: border-box;
  border: 2px solid rgba(42, 120, 214, 0.45);
  border-radius: 12px;
  background: rgba(42, 120, 214, 0.08);
  transition: left 0.18s ease, top 0.18s ease, width 0.18s ease, height 0.18s ease;
}

.dash-widget {
  position: absolute;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(11, 11, 11, 0.1);
  border-radius: 12px;
  background: #fcfcfb;
  transition: left 0.18s ease, top 0.18s ease, width 0.18s ease, height 0.18s ease, box-shadow 0.18s ease;
}

.dash-widget.is-dragging {
  z-index: 10;
  transition: box-shadow 0.18s ease;
  box-shadow: 0 8px 24px rgba(11, 11, 11, 0.16);
  cursor: grabbing;
}

.dash-widget__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 14px 0;
}

.dash-widget__grip {
  flex: 1;
  min-width: 0;
  padding: 2px 4px;
  margin: -2px -4px;
  border-radius: 6px;
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.dash-widget__grip:focus-visible {
  outline: 2px solid #2a78d6;
  outline-offset: 2px;
}

.dash-widget__title,
.dash-widget__subtitle {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dash-widget__body {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  padding: 8px 14px 12px;
}

.dash-widget__resize {
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  touch-action: none;
  background: linear-gradient(135deg, transparent 0 55%, #c3c2b7 55% 62%, transparent 62% 74%, #c3c2b7 74% 81%, transparent 81%);
}

.dash-widget.is-resizing,
.dash-widget.is-dragging {
  user-select: none;
}

/* ---------- stat tile ---------- */

.viz-stat {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
}

.viz-stat__value {
  font-size: 28px;
  font-weight: 600;
  line-height: 1.1;
}

.viz-stat__delta {
  font-size: 13px;
  font-weight: 600;
}

.viz-stat__vs {
  font-weight: 400;
  color: #52514e;
}

.viz-stat__trend {
  display: flex;
  flex: 1;
  align-items: flex-end;
  min-height: 32px;
  margin-top: 8px;
}

.viz-spark {
  width: 100%;
  height: 100%;
}

.viz-spark svg {
  display: block;
  overflow: visible;
}

/* ---------- charts ---------- */

.viz-chart {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
}

.viz-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: #52514e;
}

.viz-legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}

.viz-key {
  display: inline-block;
  flex: none;
}

.viz-key--line {
  width: 16px;
  height: 2px;
  border-radius: 1px;
}

.viz-key--rect {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

.viz-plot {
  position: relative;
  flex: 1;
  min-height: 0;
}

.viz-plot svg {
  display: block;
  overflow: visible;
}

.viz-plot svg:focus-visible {
  outline: 2px solid #2a78d6;
  outline-offset: 2px;
  border-radius: 4px;
}

.viz-chart--segmented .viz-plot {
  flex: none;
  height: 24px;
}

.viz-legend--rows {
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
  color: #0b0b0b;
}

.viz-legend--rows li {
  display: grid;
  grid-template-columns: 10px 1fr auto auto;
  gap: 8px;
  padding: 4px 6px;
  margin: 0 -6px;
  border-radius: 6px;
}

.viz-legend--rows li.is-active {
  background: rgba(11, 11, 11, 0.04);
}

.viz-legend__share {
  color: #52514e;
  font-variant-numeric: tabular-nums;
}

.viz-legend__amount {
  font-variant-numeric: tabular-nums;
  min-width: 96px;
  text-align: right;
}

.viz-tooltip {
  position: absolute;
  z-index: 2;
  pointer-events: none;
  white-space: nowrap;
  padding: 6px 10px;
  border: 1px solid rgba(11, 11, 11, 0.1);
  border-radius: 8px;
  background: #fcfcfb;
  box-shadow: 0 4px 12px rgba(11, 11, 11, 0.12);
  font-size: 12px;
  color: #52514e;
}

.viz-tooltip__caption {
  color: #898781;
  margin-bottom: 2px;
}

.viz-tooltip__row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.viz-tooltip__value {
  font-size: 13px;
  font-weight: 600;
  color: #0b0b0b;
  font-variant-numeric: tabular-nums;
}

.viz-tooltip__name {
  color: #52514e;
}

/* ---------- table view ---------- */

.viz-table-wrap {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.viz-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  color: #0b0b0b;
}

.viz-table th,
.viz-table td {
  padding: 7px 8px;
  border-bottom: 1px solid #e1e0d9;
  text-align: left;
  vertical-align: middle;
}

.viz-table th {
  position: sticky;
  top: 0;
  background: #fcfcfb;
  font-weight: 600;
  color: #52514e;
}

.viz-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .dash-widget,
  .dash-placeholder {
    transition: none;
  }
}

