  outline: 2px solid #2a78d6;
  outline-offset: 2px;
  border-radius: 4px;
}

.viz-chart--segmented .viz-plot {
  flex: none;
  height: 24px;
}

.viz-legend--rows {
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
  color: #0b0b0b;
}

.viz-legend--rows li {
  display: grid;
  grid-template-columns: 10px 1fr auto auto;
  gap: 8px;
  padding: 4px 6px;
  margin: 0 -6px;
  border-radius: 6px;
}

.viz-legend--rows li.is-active {
  background: rgba(11, 11, 11, 0.04);
}

.viz-legend__share {
  color: #52514e;
  font-variant-numeric: tabular-nums;
}

.viz-legend__amount {
  font-variant-numeric: tabular-nums;
  min-width: 96px;
  text-align: right;
}

.viz-tooltip {
  position: absolute;
  z-index: 2;
  pointer-events: none;
  white-space: nowrap;
  padding: 6px 10px;
  border: 1px solid rgba(11, 11, 11, 0.1);
  border-radius: 8px;
  background: #fcfcfb;
  box-shadow: 0 4px 12px rgba(11, 11, 11, 0.12);
  font-size: 12px;
  color: #52514e;
}

.viz-tooltip__caption {
  color: #898781;
  margin-bottom: 2px;
}

.viz-tooltip__row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.viz-tooltip__value {
  font-size: 13px;
  font-weight: 600;
  color: #0b0b0b;
  font-variant-numeric: tabular-nums;
}

.viz-tooltip__name {
  color: #52514e;
}

/* ---------- table view ---------- */

.viz-table-wrap {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.viz-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  color: #0b0b0b;
}

.viz-table th,
.viz-table td {
  padding: 7px 8px;
  border-bottom: 1px solid #e1e0d9;
  text-align: left;
  vertical-align: middle;
}

.viz-table th {
  position: sticky;
  top: 0;
  background: #fcfcfb;
  font-weight: 600;
  color: #52514e;
}

.viz-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .dash-widget,
  .dash-placeholder {
    transition: none;
  }
}

