import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:4173/';
const KEY = 'dashboard-layout:v1';
const browser = await chromium.launch({ executablePath: process.env.CHROME, args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 1000 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));

const rects = () => page.$$eval('.dash-widget', (els) => els.map((el) => {
  const r = el.getBoundingClientRect();
  return { id: el.querySelector('h2')?.textContent, x: r.x, y: r.y, w: r.width, h: r.height };
}));
const round = (rs) => rs.map(({ id, x, y, w, h }) => [id, Math.round(x), Math.round(y), Math.round(w), Math.round(h)]);
const overlapPairs = (rs) => {
  const bad = [];
  for (let i = 0; i < rs.length; i++) for (let j = i + 1; j < rs.length; j++) {
    const a = rs[i], b = rs[j];
    if (a.x < b.x + b.w - 1 && b.x < a.x + a.w - 1 && a.y < b.y + b.h - 1 && b.y < a.y + a.h - 1) bad.push(`${a.id} x ${b.id}`);
  }
  return bad;
};
const box = (title) => page.locator('.dash-widget', { hasText: title }).first();
const report = {};

await page.goto(URL, { waitUntil: 'load' });
await page.evaluate((k) => localStorage.removeItem(k), KEY);
await page.reload({ waitUntil: 'load' });
await page.waitForSelector('.dash-widget');
await page.waitForTimeout(300);
report.count = (await rects()).length;
report.initialOverlaps = overlapPairs(await rects());
await page.screenshot({ path: '/tmp/e2e/01-initial.png', fullPage: true });

// 1) mouse drag: "Каналы" (bottom-left) to the top-right area
{
  const grip = box('Каналы').locator('.dash-widget__grip');
  const gb = await grip.boundingBox();
  await page.mouse.move(gb.x + 20, gb.y + 10);
  await page.mouse.down();
  for (let s = 1; s <= 20; s++) await page.mouse.move(gb.x + 20 + (900 - gb.x) * s / 20, gb.y + 10 - 560 * s / 20);
  await page.screenshot({ path: '/tmp/e2e/02-dragging.png', fullPage: true });
  await page.mouse.up();
  await page.waitForTimeout(400);
  report.afterDragOverlaps = overlapPairs(await rects());
  report.channelsAfterDrag = round(await rects()).find((r) => r[0] === 'Каналы');
  await page.screenshot({ path: '/tmp/e2e/03-after-drag.png', fullPage: true });
}

// 2) mouse resize: "Динамика выручки" +120px wide, +70px tall
{
  const w = box('Динамика выручки');
  const b0 = await w.boundingBox();
  const h = await w.locator('.dash-widget__resize').boundingBox();
  await page.mouse.move(h.x + 8, h.y + 8);
  await page.mouse.down();
  await page.mouse.move(h.x + 128, h.y + 78, { steps: 10 });
  await page.mouse.up();
  await page.waitForTimeout(400);
  const b1 = await w.boundingBox();
  report.resize = { w: [Math.round(b0.width), Math.round(b1.width)], h: [Math.round(b0.height), Math.round(b1.height)] };
  report.afterResizeOverlaps = overlapPairs(await rects());
  await page.screenshot({ path: '/tmp/e2e/04-after-resize.png', fullPage: true });
}

// 3) keyboard: "Выручка" ArrowRight x2, then Shift+ArrowRight
{
  const w = box('Выручка');
  const k0 = await w.boundingBox();
  await w.locator('.dash-widget__grip').focus();
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('ArrowRight');
  await page.waitForTimeout(300);
  const k1 = await w.boundingBox();
  await page.keyboard.press('Shift+ArrowRight');
  await page.waitForTimeout(300);
  const k2 = await w.boundingBox();
  report.keyboard = { moveDx: Math.round(k1.x - k0.x), resizeDw: Math.round(k2.width - k1.width) };
  report.afterKeyOverlaps = overlapPairs(await rects());
}

// 4) table twin toggle on "Динамика выручки"
{
  const w = box('Динамика выручки');
  await w.getByRole('button', { name: 'Таблица' }).click();
  report.tableRows = await w.locator('tbody tr').count();
  await w.getByRole('button', { name: 'График' }).click();
}

// 5) hover tooltip on line chart
{
  const w = box('Динамика выручки');
  const svg = await w.locator('svg[role="img"]').boundingBox();
  await page.mouse.move(svg.x + svg.width * 0.5, svg.y + svg.height * 0.5);
  await page.waitForTimeout(100);
  report.lineTooltipText = await w.locator('.viz-tooltip').textContent().catch(() => null);
  await page.screenshot({ path: '/tmp/e2e/05-tooltip.png', fullPage: true });
}

// 6) persistence across reload
{
  await page.mouse.move(0, 0);
  await page.waitForTimeout(300);
  const storedBefore = await page.evaluate((k) => localStorage.getItem(k), KEY);
  const geomBefore = JSON.stringify(round(await rects()));
  await page.reload({ waitUntil: 'load' });
  await page.waitForSelector('.dash-widget');
  await page.waitForTimeout(400);
  const storedAfter = await page.evaluate((k) => localStorage.getItem(k), KEY);
  const geomAfter = JSON.stringify(round(await rects()));
  report.persisted = { storageEqual: storedBefore === storedAfter, geometryEqual: geomBefore === geomAfter };
  report.afterReloadOverlaps = overlapPairs(await rects());
}

// 7) reset
{
  await page.getByRole('button', { name: 'Сбросить раскладку' }).click();
  await page.waitForTimeout(400);
  report.afterResetOverlaps = overlapPairs(await rects());
  report.afterResetDefault = round(await rects()).find((r) => r[0] === 'Выручка');
}

report.errors = errors;
console.log(JSON.stringify(report, null, 2));
await browser.close();
EOF
