  const w = box('Выручка');
  const k0 = await w.boundingBox();
  await w.locator('.dash-widget__grip').focus();
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('ArrowRight');
  await page.waitForTimeout(300);
  const k1 = await w.boundingBox();
  await page.keyboard.press('Shift+ArrowRight');
  await page.waitForTimeout(300);
  const k2 = await w.boundingBox();
  report.keyboard = { moveDx: Math.round(k1.x - k0.x), resizeDw: Math.round(k2.width - k1.width) };
  report.afterKeyOverlaps = overlapPairs(await rects());
}

// 4) table twin toggle on "Динамика выручки"
{
  const w = box('Динамика выручки');
  await w.getByRole('button', { name: 'Таблица' }).click();
  report.tableRows = await w.locator('tbody tr').count();
  await w.getByRole('button', { name: 'График' }).click();
}

// 5) hover tooltip on line chart
{
  const w = box('Динамика выручки');
  const svg = await w.locator('svg[role="img"]').boundingBox();
  await page.mouse.move(svg.x + svg.width * 0.5, svg.y + svg.height * 0.5);
  await page.waitForTimeout(100);
  report.lineTooltipText = await w.locator('.viz-tooltip').textContent().catch(() => null);
  await page.screenshot({ path: '/tmp/e2e/05-tooltip.png', fullPage: true });
}

// 6) persistence across reload
{
  await page.mouse.move(0, 0);
  await page.waitForTimeout(300);
  const storedBefore = await page.evaluate((k) => localStorage.getItem(k), KEY);
  const geomBefore = JSON.stringify(round(await rects()));
  await page.reload({ waitUntil: 'load' });
  await page.waitForSelector('.dash-widget');
  await page.waitForTimeout(400);
  const storedAfter = await page.evaluate((k) => localStorage.getItem(k), KEY);
  const geomAfter = JSON.stringify(round(await rects()));
  report.persisted = { storageEqual: storedBefore === storedAfter, geometryEqual: geomBefore === geomAfter };
  report.afterReloadOverlaps = overlapPairs(await rects());
}

// 7) reset
{
  await page.getByRole('button', { name: 'Сбросить раскладку' }).click();
  await page.waitForTimeout(400);
  report.afterResetOverlaps = overlapPairs(await rects());
  report.afterResetDefault = round(await rects()).find((r) => r[0] === 'Выручка');
}

report.errors = errors;
console.log(JSON.stringify(report, null, 2));
await browser.close();
EOF
